import {ENEMIES,ZONES,ITEM_TEMPLATES} from '../content/region.js?v=0.3.1';
import {SETS,killXP} from '../content/progression.js?v=0.3.1';
import {CLASSES} from '../content/classes.js?v=0.3.1';
import {createItem,derive,addEffect,heal,lineOfSight} from './rules.js?v=0.3.1';
export const SET_EFFECTS={swordsman:'Після навички: захист на 2 с.',mage:'Після навички: міць на 3 с.',archer:'Після навички: ухилення на 1 с.',acolyte:'Після навички: лікування союзників поруч на 3% HP.',merchant:'Після навички: щит на 5% HP на 4 с.',thief:'Після навички: вампіризм на 3 с.',gunslinger:'Після навички: ухилення на 1 с.'};
export function activeSets(h){const counts={};for(const id of Object.values(h.equipment)){const t=ITEM_TEMPLATES[h.inventory.find(i=>i.id===id)?.template];if(t?.set)counts[t.set]=(counts[t.set]||0)+1;}return counts;}
export function setCast(sim,h){if(!Object.values(activeSets(h)).some(n=>n>=2)||(h.cooldowns.setEffect||0)>0)return;h.cooldowns.setEffect=8;const c=h.classId;if(c==='acolyte'){for(const ally of Object.values(sim.s.players))if(ally.online&&!ally.dead&&Math.hypot(ally.x-h.x,ally.y-h.y)<4&&lineOfSight(sim.s.zone,h,ally,sim.s.flags))heal(ally,derive(ally).hp*.03);}else{const e={swordsman:['guard',2],mage:['might',3],archer:['evasion',1],merchant:['shield',4],thief:['leech',3],gunslinger:['evasion',1]}[c];if(!h.effects.some(x=>x.id===e[0]&&x.left>0))addEffect(h,e[0],e[1],h.id,c==='merchant'?derive(h).hp*.05:0);}sim.event('buff',{actor:h.id,text:'Відгук комплекту'});}
export function trophySet(h,type){const e=ENEMIES[type];return e&&Object.entries(SETS).filter(([,s])=>s.classId===h.classId&&s.level<=e.level).at(-1);}
export function recordHunt(h,e,xp){if(e.mechanicTarget)return;h.bestiary??={};const b=h.bestiary[e.type]??={kills:0,trophies:0};b.kills++;if(xp>0)b.trophies=Math.min(9999,b.trophies+(e.boss?5:1));}
export function growthCommand(sim,h,i){if(!['trophyCraft','buildSave','buildApply'].includes(i.type))return null;if(h.dead||h.cast)throw Error('Завершіть бій або поверніться до життя');const safe=ZONES[sim.s.zone].objects.some(o=>['camp','forge','storage'].includes(o.kind)&&Math.hypot(o.x-h.x,o.y-h.y)<3&&lineOfSight(sim.s.zone,h,o,sim.s.flags))&&!sim.s.enemies.some(e=>!e.dead&&(e.aggroTarget===h.id||e.aggression==='aggressive'&&Math.hypot(e.x-h.x,e.y-h.y)<e.aggroRange));if(!safe)throw Error('Потрібен привал, кузня або сховище поза боєм');
if(i.type==='trophyCraft'){const entry=trophySet(h,i.enemy),b=h.bestiary?.[i.enemy];if(!entry||!entry[1].pieces.includes(i.template)||!b||b.trophies<20||h.level<entry[1].level)throw Error('Потрібні 20 трофеїв цього ворога та рівень комплекту');b.trophies-=20;h.inventory.push(createItem(i.template,h.id,{bound:true}));return{};}
if(!Number.isInteger(i.slot)||i.slot<0||i.slot>1)throw Error('Невірний набір');h.builds??=[null,null];if(i.type==='buildSave'){h.builds[i.slot]={equipment:{...h.equipment},skillbar:[...h.skillbar],augments:{...h.skillAugments}};return{};}
const b=h.builds[i.slot];if(!b)throw Error('Спочатку збережіть набір');for(const [slot,id]of Object.entries(b.equipment)){if(!id)continue;const item=h.inventory.find(x=>x.id===id&&x.owner===h.id),t=ITEM_TEMPLATES[item?.template];if(!t||(t.slot||t.kind)!==slot||h.level<t.requirements.level||t.requirements.classes&&!t.requirements.classes.includes(h.classId)||sim.s.offers.some(o=>o.item===id&&o.status==='pending'))throw Error('Предмет відсутній у торбі, недоступний або зарезервований');}if(b.skillbar.length!==2||new Set(b.skillbar).size!==2||b.skillbar.some(id=>!h.skillRanks[id]||!CLASSES[h.classId].skills.some(s=>s.id===id)))throw Error('Навички набору недоступні');let cost=0;for(const [id,choice]of Object.entries(b.augments)){if(!h.skillRanks[id]||!['force','rhythm'].includes(choice)||h.level<10)throw Error('Підсилення недоступне');if(h.skillAugments[id]!==choice)cost+=h.skillAugments[id]?3:2;}if(h.echoes<cost)throw Error('Для зміни напрямів потрібно відлунь: '+cost);h.echoes-=cost;h.equipment={...b.equipment};h.skillbar=[...b.skillbar];Object.assign(h.skillAugments,b.augments);const d=derive(h);h.hp=Math.min(h.hp,d.hp);h.sp=Math.min(h.sp,d.sp);h.auto=false;h.path=[];return{};}
export function validateGrowth(h){if(h.bestiary!==undefined){if(!h.bestiary||typeof h.bestiary!=='object'||Array.isArray(h.bestiary))throw Error('Невірний бестіарій');for(const [id,b]of Object.entries(h.bestiary))if(!Object.hasOwn(ENEMIES,id)||!b||!Number.isSafeInteger(b.kills)||b.kills<0||!Number.isInteger(b.trophies)||b.trophies<0||b.trophies>9999)throw Error('Невірні трофеї');}if(h.builds!==undefined){if(!Array.isArray(h.builds)||h.builds.length!==2)throw Error('Невірні набори');for(const b of h.builds){if(b===null)continue;if(!b||!b.equipment||Object.keys(b.equipment).sort().join()!=='accessory,armor,weapon'||Object.values(b.equipment).some(id=>id!==null&&typeof id!=='string')||!Array.isArray(b.skillbar)||b.skillbar.length!==2||new Set(b.skillbar).size!==2||b.skillbar.some(id=>!CLASSES[h.classId].skills.some(s=>s.id===id))||!b.augments||Object.entries(b.augments).some(([id,c])=>!CLASSES[h.classId].skills.some(s=>s.id===id)||!['force','rhythm'].includes(c)))throw Error('Невірний набір');}}}
